SEP = 'https://plato.stanford.edu/entries/'
ROT_PESO = {'forte': 'A evidência pesa claramente para um lado', 'parcial': 'Um lado tem mais apoio, com ressalvas', 'aberto': 'Debate em aberto'}
TEMAS_DB = ['O que é ciência', 'Saúde e evidência', 'Ciência e sociedade', 'Ética na pesquisa']
def D(s, n, t, r, v, lados, visoes, c, p, licoes, fx):
    return dict(s=s, n=n, t=t, r=r, v=v, lados=lados, visoes=visoes, c=c, p=p, licoes=licoes, fx=fx)

