  [('falsificacionismo', 'Popper criticava teorias econômicas historicistas, como a de Marx, mas admitia uma ciência social de hipóteses testáveis.'), ('programas-de-pesquisa', 'Lakatos sugeria avaliar escolas econômicas como programas de pesquisa, progressivos ou degenerativos.'), ('realismo-de-entidades', 'Cartwright discute quando resultados de experimentos econômicos valem para outros contextos.')],
